-- Generated by pwc-to-dbt from PowerCenter mapping m_FL_JS_MARTS_ENRICHED: target STORE_DAILY_KPIS (instance STORE_DAILY_KPIS).
-- Do not edit by hand; change the mapping or the converter and regenerate.
-- Flow: SRT_BEFORE_AGG -> SRT_FOR_DISTINCT_CUSTOMER -> EXP_MARK_FIRST_CUSTOMER -> AGG_BY_LOCATION_DAY -> EXP_STORE_KPIS -> SQ_STG_LOCATIONS1 -> JNR_ADD_LOCATION_INFO -> FIL_LOCS -> STORE_DAILY_KPIS
-- WARNING [EXP_MARK_FIRST_CUSTOMER]: v_PREV_LOCATION is read by a variable above it, so that read sees the previous row's value (lag)
-- WARNING [EXP_MARK_FIRST_CUSTOMER]: v_PREV_DAY is read by a variable above it, so that read sees the previous row's value (lag)
-- WARNING [EXP_MARK_FIRST_CUSTOMER]: v_PREV_CUSTOMER is read by a variable above it, so that read sees the previous row's value (lag)

with

srt_before_agg as (
    -- SRT_BEFORE_AGG (Sorter on location_id asc, ordered_at_day asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        location_id as location_id,
        order_id as order_id,
        customer_id as customer_id,
        ordered_at_day as ordered_at_day,
        order_total as order_total,
        order_subtotal as order_subtotal,
        order_tax_paid as order_tax_paid,
        order_cogs as order_cogs,
        order_gross_profit as order_gross_profit,
        order_value_band as order_value_band
    from {{ ref('int_fl_js_marts_enriched__un_order_bands') }}
),

srt_for_distinct_customer as (
    -- SRT_FOR_DISTINCT_CUSTOMER (Sorter on location_id asc, ordered_at_day asc, customer_id asc, order_id asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        location_id as location_id,
        ordered_at_day as ordered_at_day,
        customer_id as customer_id,
        order_id as order_id,
        order_total as order_total,
        order_subtotal as order_subtotal,
        order_tax_paid as order_tax_paid,
        order_cogs as order_cogs,
        order_gross_profit as order_gross_profit,
        order_value_band as order_value_band
    from srt_before_agg
),

exp_mark_first_customer as (
    -- EXP_MARK_FIRST_CUSTOMER (Expression)
    select
        location_id as location_id,
        ordered_at_day as ordered_at_day,
        customer_id as customer_id,
        order_id as order_id,
        order_total as order_total,
        order_subtotal as order_subtotal,
        order_tax_paid as order_tax_paid,
        order_cogs as order_cogs,
        order_gross_profit as order_gross_profit,
        order_value_band as order_value_band,
        (case when (((lag(location_id, 1, '') over (order by location_id asc, ordered_at_day asc, customer_id asc, order_id asc) = location_id) and (lag(ordered_at_day, 1, timestamp '1753-01-01') over (order by location_id asc, ordered_at_day asc, customer_id asc, order_id asc) = ordered_at_day)) and (lag(customer_id, 1, '') over (order by location_id asc, ordered_at_day asc, customer_id asc, order_id asc) = customer_id)) then 0 else 1 end) as is_first_customer
    from srt_for_distinct_customer
),

agg_by_location_day as (
    -- AGG_BY_LOCATION_DAY (Aggregator) grouped by LOCATION_ID, ORDERED_AT_DAY
    select
        location_id as location_id,
        ordered_at_day as ordered_at_day,
        count(order_id) as orders_count,
        sum(is_first_customer) as unique_customers,
        sum(order_total) as revenue_total,
        sum(order_subtotal) as subtotal_total,
        sum(order_tax_paid) as tax_total,
        sum(order_cogs) as cogs_total,
        sum(order_gross_profit) as gross_profit_total,
        sum(case when (order_value_band = 'HIGH') then 1 else 0 end) as high_value_orders
    from exp_mark_first_customer
    group by location_id, ordered_at_day
),

exp_store_kpis as (
    -- EXP_STORE_KPIS (Expression)
    select
        location_id as location_id,
        ordered_at_day as ordered_at_day,
        orders_count as orders_count,
        unique_customers as unique_customers,
        revenue_total as revenue_total,
        subtotal_total as subtotal_total,
        tax_total as tax_total,
        cogs_total as cogs_total,
        gross_profit_total as gross_profit_total,
        high_value_orders as high_value_orders,
        case when (subtotal_total = 0) then 0 else (gross_profit_total / subtotal_total) end as gross_margin_pct,
        case when (orders_count = 0) then 0 else (revenue_total / orders_count) end as avg_order_value,
        case when (orders_count = 0) then 0 else (high_value_orders / orders_count) end as high_value_orders_pct
    from agg_by_location_day
),

sq_stg_locations1 as (
    -- SQ_STG_LOCATIONS1 (Source Qualifier): reads STG_LOCATIONS
    select
        cast(location_id as varchar) as location_id,
        cast(location_name as varchar) as location_name,
        cast(opened_date as timestamp) as opened_date,
        cast(tax_rate as decimal(6, 4)) as tax_rate,
        cast(region as varchar) as region
    from {{ ref('stg_locations') }}
),

jnr_add_location_info as (
    -- JNR_ADD_LOCATION_INFO (Joiner, Master Outer Join): LOCATION_ID = LOCATION_ID1
    select
        master.location_id as location_id,
        detail.location_name as location_name,
        detail.region as region,
        master.ordered_at_day as ordered_at_day,
        master.orders_count as orders_count,
        master.unique_customers as unique_customers,
        master.revenue_total as revenue_total,
        master.subtotal_total as subtotal_total,
        master.tax_total as tax_total,
        master.cogs_total as cogs_total,
        master.gross_profit_total as gross_profit_total,
        master.gross_margin_pct as gross_margin_pct,
        master.avg_order_value as avg_order_value,
        master.high_value_orders as high_value_orders,
        master.high_value_orders_pct as high_value_orders_pct
    from sq_stg_locations1 as detail
    left join exp_store_kpis as master
        on (master.location_id = detail.location_id)
),

fil_locs as (
    -- FIL_LOCS (Filter): keeps rows where NOT ISNULL(LOCATION_ID)
    select
        location_id as location_id,
        location_name as location_name,
        region as region,
        ordered_at_day as ordered_at_day,
        orders_count as orders_count,
        unique_customers as unique_customers,
        revenue_total as revenue_total,
        subtotal_total as subtotal_total,
        tax_total as tax_total,
        cogs_total as cogs_total,
        gross_profit_total as gross_profit_total,
        gross_margin_pct as gross_margin_pct,
        avg_order_value as avg_order_value,
        high_value_orders as high_value_orders,
        high_value_orders_pct as high_value_orders_pct
    from jnr_add_location_info
    where (not (location_id is null))
),

final as (
    -- STORE_DAILY_KPIS (Target STORE_DAILY_KPIS): cast to the target column types
    select
        cast(location_id as varchar) as location_id,
        cast(location_name as varchar) as location_name,
        cast(region as varchar) as region,
        cast(ordered_at_day as timestamp) as ordered_at_day,
        cast(orders_count as decimal(15, 0)) as orders_count,
        cast(unique_customers as decimal(15, 0)) as unique_customers,
        cast(revenue_total as decimal(12, 2)) as revenue_total,
        cast(subtotal_total as decimal(12, 2)) as subtotal_total,
        cast(tax_total as decimal(12, 2)) as tax_total,
        cast(cogs_total as decimal(12, 2)) as cogs_total,
        cast(gross_profit_total as decimal(12, 2)) as gross_profit_total,
        cast(gross_margin_pct as decimal(10, 4)) as gross_margin_pct,
        cast(avg_order_value as decimal(12, 2)) as avg_order_value,
        cast(high_value_orders as decimal(15, 0)) as high_value_orders,
        cast(high_value_orders_pct as decimal(10, 4)) as high_value_orders_pct
    from fil_locs
)

select * from final
